\begin{assumption}\label{assumption:j}
%======================================================
The functional $j \colon O\to\R$ is twice continuously 
differentiable. We assume that for every $h \in X_{ad},$ %there exists $\overline{r} \in X$ 
%satisfying \eqref{eq:OC} such that for all $r$ on a 
%neighborhood $\overline{B_{\delta}^X(\overline{r})}$ of 
%$\overline{r}$, 
the second derivative $D^2 j(h)\in 
\mathcal{L}(X,X^*)$ extends continuously to a bilinear 
form on $H\times H$, i.e., there exists $C_S >0$ such that 
\begin{equation}\label{eq:assumption-continuity-bilinear-form}
%======================================================================
    |D^2 j(h)[q_1,q_2]| \leq C_S \lVert q_1 \rVert_H \lVert q_2 \rVert_H  
    \ \forall q_1, q_2 \in H.
\end{equation}
Additionally, we assume that for there exists $c_E >0$ such that 
the following strong coercivity condition is satisfied for every $h \in X_{ad}$:
\begin{equation}
    \label{eq:strong-coercivity} 
    D^2j(h)[q,q] \ge c_E \lVert q\rVert_H^2 
    \quad \forall q \in H.
\end{equation}
\end{assumption}

which is well-defined and single-valued since $X_{ad} \subset X$ is assumed to be nonempty, closed, and convex.   We assume that it is possible to compute an approximation of the gradient in the form of a \textit{stochastic gradient} $G\colon X \times \Xi \rightarrow X$, which is defined as the (parameterized) Riesz representative of the mapping $D\mathcal{J}(\cdot,\hat{\xi}) \colon X \rightarrow X^*$, i.e., we have for every $\hat{\xi} \in \Xi$ that
\begin{equation}
\label{eq:grad_projection}
%==========================================
(G(h,\hat{\xi}),q)_X = \langle D\mathcal{J}(h,\hat{\xi}),q\rangle_{X^*,X} \quad \forall (h,q) \in X_{ad}\times X.
\end{equation}

We use the notation $\nabla j$ for the  gradient of $j$ in $X$, i.e., $(\nabla j(h),q)_{X} = \langle Dj(h),q\rangle_{X^*,X}$, where $h,q \in X$. 
The projected stochastic gradient method relies on a recursion of the form
\begin{equation}
\label{eq:SGM-recursion}
h_{n+1} := \pi_{X_{ad}}(h_n - t_n G(h_n,\xi_n)),
\end{equation}

\begin{assumption}\label{assumption:gradient}
Let $\{\mathcal{F}_n \}$ be an increasing sequence of $\sigma$-algebras.  For each $n$, there exist $b_n$, $w_n$ with
$$b_n = \E[G(h_n,\xi_n) | \mathcal{F}_n] - \nabla j(h_n), \quad w_n = G(h_n, \xi_n) - \E[G(h_n, \xi_n) | \mathcal{F}_n],$$ 
which satisfy the following assumptions:\\ (i) $ h_n$ and $b_n $ are $\mathcal{F}_n$-measurable; (ii) for $K_n:=\esssup_{\omega \in \Omega} \lVert b_n(\omega)\rVert_X$ we have that \mbox{$ \sum_{n=1}^\infty t_n K_n< \infty$} and \mbox{$\sup_n K_n < \infty$}; (iii) there exists $M\geq 0$ such that $\E[\lVert G(h,\xi)\rVert_X^2] \leq M$ for all $r \in X_{ad}$.
\end{assumption}

