\begin{theorem}\label{lemma:convergenceofPSG}
Suppose that Assumption~\ref{assumption:j} and Assumption~\ref{assumption:gradient} hold. If the sequence of step sizes satisfy \eqref{eq:RobbinsMonroStepSize}, then for iterates defined by the recursion \eqref{eq:SGM-recursion}, we have
\begin{enumerate}
 \item $\{j(h_n) \}$ converges a.s.\,and $\lim_{n \rightarrow \infty} j(h_n) = j(h^*)$,
 \item $\{h_n\}$ almost surely converges weakly in $X$ to $h^*$, and
 \item $\{h_n \}$ almost surely converges strongly in $H$ to $h^*$. 
\end{enumerate}
\end{theorem}

