proof.raw_tex:
The inequality \eqref{eq:strong-coercivity} implies strong convexity with respect to $H$. Indeed, a Taylor expansion around any point $h' \in X_{ad}$ gives \[j(h'+q)=j(h')+Dj(h')[q]+\tfrac{1}{2}D^2j(\eta)[q,q]\] with $\eta$ being a point on the segment between $h'$ and $h'+q$. Therefore,
 \begin{equation}
 \label{eq:strong-convexity}
 j(h'+q) - j(h') \geq Dj(h')[q] + \frac{c_E}{2} \lVert q \rVert^2_H
 \end{equation}
 provided that $h'+q \in X_{ad}$. If $h'=h^*$ is a (local) optimum, we have using \eqref{eq:OC} that
 \begin{equation}
  \label{eq:strong-convexity-2}
 j(h)-j(h^*) \geq \frac{c_E}{2} \lVert h-h^*\rVert_H^2 \quad \forall h \in X_{ad}.
 \end{equation}
In particular, $h^*$ is a strict minimizer in $X$ since $j(h) > j(h^*)$ for $h\neq h^*.$


\begin{lemma}[Robbins--Siegmund \cite{Robbins1971}]\label{lemma:convegence_nonnegative_supermartingales}
Assume that $\{\mathcal{F}_n\}$ is a filtration and $v_n$,
$a_n$, $b_n$, $c_n$ nonnegative random variables adapted to $\{\mathcal{F}_n\}$. If
$$\mathbb{E} [v_{n+1}| \mathcal{F}_n ] \leq v_n(1 + a_n) + b_n - c_n \mbox{ a.s. }$$
and $\sum_{n=1}^{\infty} a_n < \infty, \, \sum_{n=1}^{\infty} b_n < \infty$ a.s.,
then with probability one, $\lbrace v_n \rbrace $ is
convergent and $\sum_{n=1}^{\infty} c_n < \infty.$
\end{lemma}

\begin{proposition}[\cite{Geiersbach2019a}]
\label{prop:technicalproposition}
Let $\{\tau_n \}$ be a nonnegative deterministic sequence and $\{ \beta_n\}$ a nonnegative random sequence in $\mathbb{R}$ adapted to $\{\mathcal{F}_n$\}. Assume that
$\sum_{n=1}^\infty \tau_n = \infty$ and  $\mathbb{E} [\sum_{n=1}^\infty \tau_n \beta_n] < \infty$. Moreover assume that 
$\beta_{n} - \mathbb{E}[\beta_{n+1}|\mathcal{F}_n] \leq \gamma \tau_n$ a.s.~for all $n$ and some $\gamma > 0$. Then
$$\beta_n  \hbox{ converges to } 0  \hbox{ a.s. }$$
\end{proposition}

\begin{proof}
Recall that since $j$ is strongly convex with respect to $H$, a unique minimum $h^*\in X_{ad}$ exists. We note that $\pi_{X_{ad}}(h^*) = h^*$. Now, with $g_n:=G(h_n,\xi_n)$, we use the nonexpansivity of the projection to obtain
\begin{equation}
\label{eq:first-steps-convergence}
\begin{aligned}
    \lVert h_{n+1} -h^* \lVert_X^2 &= \lVert \pi_{X_{ad}} (h_n - t_n g_n) - \pi_{X_{ad}}(h^*)\rVert_X^2\\
    & \leq \lVert h_n - t_n g_n - h^*\lVert_X^2\\
    &=\lVert h_n - h^* \lVert_X^2 - 2t_n ( g_n, h_n-h^*)_X + t_n^2 \lVert  g_n\rVert_X^2.
   % &=\lVert h_n - h^* \lVert_X^2 - 2t_n  D\mathcal{J}(h_n,\xi_n)[ h_n-h^*] + t_n^2 \lVert  g_n\rVert_X^2.
\end{aligned}
\end{equation}

Due to (strong) convexity and the fact that $h_n, h^* \in X_{ad}$, we have 
\[ j(h^*) - j(h_n) \geq Dj(h_n)[h^*-h_n] + \frac{c_E}{2}\lVert h^*-h_n\rVert_H^2 \geq Dj(h_n)[h^*-h_n]\]
so that $-(j(h_n) - j(h^*)) \geq -D j(h_n)[h_n-h^*]=- (\nabla j(h_n), h_n-h^*)_X$. Moreover, optimality of $h^*$ gives \eqref{eq:OC}.
Taking the conditional expectation on both sides of \eqref{eq:first-steps-convergence} and applying Cauchy--Schwarz for the bias term, we have
\begin{equation}
\label{eq:conditional-inequality}
\begin{aligned}
\E[\lVert h_{n+1} -h^* \lVert_X^2|\mathcal{F}_n] &\leq \lVert h_n - h^* \lVert_X^2 - 2t_n ( \nabla j(h_n)+b_n, h_n-h^*)_X + t_n^2 \E[\lVert g_n\rVert_X^2|\mathcal{F}_n]\\
&\leq (1+2t_nK_n)\lVert h_n - h^* \lVert_X^2 -2t_n(j(h_n)-j(h^*)) + t_n^2 M.
\end{aligned}
\end{equation}
Lemma~\ref{lemma:convegence_nonnegative_supermartingales} implies that $\{\lVert h_n - h^*\rVert_X \}$ is a.s.~convergent and $\sum_{n=1}^\infty t_n (j(h_n)-j(h^*)) < \infty$ a.s., from which we can conclude that $\liminf_{n \rightarrow \infty} j(h_n) = j(h^*)$ with probability one. To show that in fact $\lim_{n\rightarrow \infty} j(h_n) = j(h^*)$, can use a simpler argument than in \cite[Theorem 3.6]{Geiersbach2019a} since we assumed $X_{ad}$ to be bounded. Indeed, applying expectation \eqref{eq:conditional-inequality} and again using Lemma~\ref{lemma:convegence_nonnegative_supermartingales}, we obtain  that $\sum_{n=1}^\infty t_n \E[j(h_n)-j(h^*)] < \infty$ surely. Convexity of $j$ implies that 
\begin{align*}
    j(h_n)-j(h_{n+1}) &\leq (\nabla j(h_n),h_n-h_{n+1})_X\\
    & \leq \lVert \nabla j(h_n) \rVert_X \lVert h_n-h_{n+1}\rVert_X\\
    & =\lVert \nabla j(h_n) \rVert_X \lVert \pi_{X_{ad}}(h_n)-\pi_{X_{ad}}(h_{n}-t_n g_n)\rVert_X\\
    & \leq \lVert \nabla j(h_n) \rVert_X \lVert t_n g_n\rVert_X.
\end{align*}
Since $X_{ad}$ is bounded, so is $\{h_n\}$, and so there exists a $\tilde{M}>0$ such that $ \lVert \nabla j(h_n) \rVert_X \leq \tilde{M}$ for all $n$. After applying the conditional expectation, we have that 
\[
j(h_n)-\E[j(h_{n+1})|\mathcal{F}_n] \leq t_n \tilde{M} \E[\lVert g_n\rVert_X|\mathcal{F}_n].
\] 
From Jensen's inequality, we see that 
\[
(\E[\lVert g_n\rVert_X|\mathcal{F}_n])^2 \leq \E[\lVert g_n\rVert_X^2|\mathcal{F}_n] \leq M,
\]
from which we can conclude that $j(h_n)-\E[j(h_{n+1})|\mathcal{F}_n] \leq t_n \tilde{M} M.$
Now, we can apply Proposition~\ref{prop:technicalproposition} to conclude that  $\lim_{n\rightarrow \infty} j(h_n) = j(h^*) = 0$, which was the first claim.

For the second claim, we observe an arbitrary trajectory of the random sequence $\{h_n\}$. Since $\{\lVert h_n -h^*\rVert_X^2\}$ is convergent, it is also bounded. In particular, there exists a weak accumulation point $\bar{h} \in X_{ad}$ of the sequence $\{h_n\}$. Let $\{h_{n_k}\}$ be a subsequence such that $h_{n_k}\rightharpoonup_X \bar{h}$. By weak lower semicontinuity of $j$ (which follows from the continuity and convexity of $j$ in $X$), we have
\[
j(\bar{h})\leq \lim_{k\rightarrow \infty} j(h_{n_k}) = j(h^*),
\]
where equality follows by the first part of this proof. Since $h^*$ is the (unique) minimizer, it follows that $j(h^*) = j(\bar{h})$, from which we can conclude that $h^* = \bar{h}$. The accumulation point being unique gives in fact $h_{n} \rightharpoonup_X h^*$ with probability one.

The third claim follows now directly from \eqref{eq:strong-convexity-2}, namely that $\lVert h_n - h^*\rVert_H^2 \rightarrow 0$ a.s.~as $n \rightarrow \infty$.
\end{proof}

